// ==================== LESSON 1: LADDER DESCENT ANIMATION ENGINE ====================
let ladderAnimationTimer = null;
let ladderTime = 0;
const totalLadderDuration = 15; // seconds
const ladderClimber = document.getElementById('ladder-climber');
const trackerDot = document.getElementById('tracker-dot');
const displayTimeL1 = document.getElementById('display-time-l1');
const displayStatusL1 = document.getElementById('display-status-l1');
const btnPlayL1 = document.getElementById('btn-play-l1');

function toggleLadderAnimation() {
    if (ladderAnimationTimer) {
        // Pause animation
        clearInterval(ladderAnimationTimer);
        ladderAnimationTimer = null;
        if (btnPlayL1) btnPlayL1.innerText = 'Resume Journey';
        if (displayStatusL1) displayStatusL1.innerText = 'Paused';
    } else {
        // Start animation loop
        if (btnPlayL1) btnPlayL1.innerText = 'Pause Journey';
        if (displayStatusL1) displayStatusL1.innerText = 'Climbing';
        if (trackerDot) trackerDot.style.display = 'block';

        ladderAnimationTimer = setInterval(() => {
            ladderTime += 0.05;
            if (ladderTime >= totalLadderDuration) {
                ladderTime = totalLadderDuration;
                clearInterval(ladderAnimationTimer);
                ladderAnimationTimer = null;
                if (btnPlayL1) btnPlayL1.innerText = 'Restart Journey';
                if (displayStatusL1) displayStatusL1.innerText = 'Completed';
            }
            updateLadderState(ladderTime);
        }, 50);
    }
}

function resetLadderAnimation() {
    if (ladderAnimationTimer) {
        clearInterval(ladderAnimationTimer);
        ladderAnimationTimer = null;
    }
    ladderTime = 0;
    updateLadderState(0);
    if (btnPlayL1) btnPlayL1.innerText = 'Start Journey';
    if (displayStatusL1) displayStatusL1.innerText = 'Ready';
    if (trackerDot) trackerDot.style.display = 'none';
}

// Calculate and update the physical and graphed position coordinates
function updateLadderState(time) {
    let height = 10;
    let statusText = 'Descending';

    // Reset segment highlight stylings
    for (let i = 1; i <= 4; i++) {
        const segEl = document.getElementById(`segment-info-${i}`);
        if (segEl) {
            segEl.className = 'lesson-segment-item';
        }
    }

    if (time <= 6) {
        // Interval 1: 0 to 6 seconds. Linear descent from 10ft down to 3ft.
        height = 10 - (7 / 6) * time;
        const s1 = document.getElementById('segment-info-1');
        if (s1) s1.className = 'lesson-segment-item font-bold text-rose-500';
    } else if (time <= 8.5) {
        // Interval 2: 6 to 8.5 seconds. Drinking water (stays flat at 3ft)
        height = 3;
        statusText = 'Drinking Water';
        const s2 = document.getElementById('segment-info-2');
        if (s2) s2.className = 'lesson-segment-item font-bold text-rose-500';
    } else if (time <= 10) {
        // Interval 3: 8.5 to 10 seconds. Descent to ground (3ft to 0ft)
        height = 3 - (3 / 1.5) * (time - 8.5);
        const s3 = document.getElementById('segment-info-3');
        if (s3) s3.className = 'lesson-segment-item font-bold text-rose-500';
    } else {
        // Interval 4: 10 to 15 seconds. Walk in the kitchen (0ft elevation)
        height = 0;
        statusText = 'Walking into kitchen';
        const s4 = document.getElementById('segment-info-4');
        if (s4) s4.className = 'lesson-segment-item font-bold text-rose-500';
    }

    // Limit bounds safely
    height = Math.max(0, Math.min(10, height));

    // Update physical climber height on page layout
    const bottomPercent = 24 + (height * 22.8);
    if (ladderClimber) ladderClimber.style.bottom = `${bottomPercent}px`;
    const bubble = document.getElementById('elevation-bubble');
    if (bubble) bubble.innerText = `Height: ${height.toFixed(1)} ft`;
    if (displayTimeL1) displayTimeL1.innerText = time.toFixed(1);
    if (displayStatusL1) displayStatusL1.innerText = statusText;

    // Map graph tracking node position
    const trackerX = 40 + (time / 15) * 340;
    const trackerY = 260 - (height / 10) * 240;

    if (trackerDot) {
        trackerDot.setAttribute('cx', trackerX);
        trackerDot.setAttribute('cy', trackerY);
    }
}

// ==================== USER CUSTOM STORY PLOTTER ====================
function updateCustomGraph() {
    const valAEl = document.getElementById('custom-val-a');
    const valBEl = document.getElementById('custom-val-b');
    const valCEl = document.getElementById('custom-val-c');
    if (!valAEl || !valBEl || !valCEl) return;

    const valA = parseFloat(valAEl.value);
    const valB = parseFloat(valBEl.value);
    const valC = parseFloat(valCEl.value);

    // Update text labels
    const lblA = document.getElementById('custom-lbl-a');
    const lblB = document.getElementById('custom-lbl-b');
    const lblC = document.getElementById('custom-lbl-c');
    if (lblA) lblA.innerText = valA;
    if (lblB) lblB.innerText = valB;
    if (lblC) lblC.innerText = valC;

    // Update SVG nodes
    const yA = 170 - (valA / 15) * 150;
    const yB = 170 - (valB / 15) * 150;
    const yC = 170 - (valC / 15) * 150;

    const nodeA = document.getElementById('user-node-a');
    const nodeB = document.getElementById('user-node-b');
    const nodeC = document.getElementById('user-node-c');
    if (nodeA) nodeA.setAttribute('cy', yA);
    if (nodeB) nodeB.setAttribute('cy', yB);
    if (nodeC) nodeC.setAttribute('cy', yC);

    // Reconstruct path string
    const pathD = `M 30,170 L 130,${yA} L 205,${yB} L 280,${yC}`;
    const pathEl = document.getElementById('user-graph-path');
    if (pathEl) pathEl.setAttribute('d', pathD);

    // Generate verbal descriptions
    const storyList = document.getElementById('custom-story-output');
    if (!storyList) return;
    storyList.innerHTML = '';

    let segment1Text = `0 to 4s: Climber `;
    if (valA > 0) {
        segment1Text += `climbs from ground level to ${valA} feet.`;
    } else {
        segment1Text += `remains flat at ground level.`;
    }

    let segment2Text = `4 to 7s: Climber `;
    if (valB > valA) {
        segment2Text += `continues climbing up from ${valA} feet to ${valB} feet.`;
    } else if (valB < valA) {
        segment2Text += `descends down from ${valA} feet to ${valB} feet.`;
    } else {
        segment2Text += `remains completely stationary at ${valA} feet.`;
    }

    let segment3Text = `7 to 10s: Climber `;
    if (valC > valB) {
        segment3Text += `ascends up to ${valC} feet.`;
    } else if (valC < valB) {
        segment3Text += `descends down to ${valC} feet.`;
    } else {
        segment3Text += `holds position constant at ${valB} feet.`;
    }

    storyList.innerHTML += `<li>${segment1Text}</li>`;
    storyList.innerHTML += `<li>${segment2Text}</li>`;
    storyList.innerHTML += `<li>${segment3Text}</li>`;
}

// ==================== LESSON VOCAB & NOTES FUNCTIONALITY ====================
function toggleVocabCard(id) {
    const body = document.getElementById(`${id}-body`);
    const icon = document.getElementById(`${id}-icon`);
    if (!body) return;

    if (body.style.maxHeight && body.style.maxHeight !== '0px') {
        body.style.maxHeight = '0px';
        if (icon) icon.innerHTML = '<i class="fas fa-chevron-down"></i>';
    } else {
        // Close other open cards
        const allBodies = document.querySelectorAll('[id$="-body"]');
        const allIcons = document.querySelectorAll('[id$="-icon"]');
        allBodies.forEach(b => {
            if (b.id.startsWith('vocab-')) b.style.maxHeight = '0px';
        });
        allIcons.forEach(i => {
            if (i.id.startsWith('vocab-')) i.innerHTML = '<i class="fas fa-chevron-down"></i>';
        });

        body.style.maxHeight = body.scrollHeight + 'px';
        if (icon) icon.innerHTML = '<i class="fas fa-chevron-up"></i>';
    }
}

function switchExplainerTab(tabId) {
    const tabs = ['tab-slope', 'tab-intervals', 'tab-speed'];

    tabs.forEach(t => {
        const btn = document.getElementById(`btn-${t}`);
        const content = document.getElementById(`content-${t}`);

        if (t === tabId) {
            if (btn) btn.classList.add('active');
            if (content) content.classList.add('active');
        } else {
            if (btn) btn.classList.remove('active');
            if (content) content.classList.remove('active');
        }
    });
}

document.addEventListener('DOMContentLoaded', () => {
    updateCustomGraph();
});
if (document.readyState === 'complete' || document.readyState === 'interactive') {
    setTimeout(updateCustomGraph, 100);
}
